24	static Var getPlaceholder(const std::string &s) {
25	  static std::unordered_map<std::string, Var> map;
26	  if (map.find(s) == map.end()) {
27	    map[s] = Var(s);
28	  }
29	  return map[s];
30	}
31	
32	Var ReplicationPlaceholder() { return getPlaceholder("_rep"); }
33	Var InputPlaceholder(size_t idx) {
34	  return getPlaceholder(std::string{'_', char('i' + idx)});
35	}
