37	Map<Var, Range> LayoutNode::getVarMap() const {
38	  Map<Var, Range> map;
39	  for (size_t i = 0; i < InputDim(); i++) {
40	    map.Set(InputPlaceholder(i), {0, input_size_[i]});
41	  }
42	  return map;
43	}
