51	LayoutNode::LayoutNode(Array<PrimExpr> input_size,
52	                       Array<PrimExpr> forward_index) {
53	  input_size_ = input_size;
54	  arith::Analyzer analyzer;
55	  UpdateAnalyzer(&analyzer);
56	  forward_index_ = forward_index.Map(
57	      [&](const PrimExpr &e) { return analyzer.Simplify(e); });
58	}
