60	Layout::Layout(Array<IterVar> forward_var, Array<PrimExpr> forward_index) {
61	  Map<Var, PrimExpr> vmap;
62	  Array<PrimExpr> input_size;
63	  for (size_t i = 0; i < forward_var.size(); i++) {
64	    vmap.Set(forward_var[i]->var, InputPlaceholder(i));
65	    CHECK(is_zero(forward_var[i]->dom->min));
66	    input_size.push_back(forward_var[i]->dom->extent);
67	  }
68	  forward_index =
69	      forward_index.Map([&](const PrimExpr &e) { return Substitute(e, vmap); });
70	  auto n = tvm::ffi::make_object<LayoutNode>(input_size, forward_index);
71	  data_ = std::move(n);
72	}
