93	Array<PrimExpr> LayoutNode::GetForwardVars() const {
94	  Array<PrimExpr> vars;
95	  for (size_t i = 0; i < InputDim(); i++) {
96	    vars.push_back(InputPlaceholder(i));
97	  }
98	  return vars;
