101	Array<PrimExpr> LayoutNode::OutputShape() const {
102	  Array<PrimExpr> ret(OutputDim(), 1);
103	  arith::Analyzer analyzer;
104	  UpdateAnalyzer(&analyzer);
105	  for (size_t i = 0; i < ret.size(); i++) {
106	    auto ist = analyzer.int_set(forward_index_[i] + 1);
107	    if (arith::is_neg_inf(ist.min()) && arith::is_pos_inf(ist.max())) {
108	      // Analyzer couldn't form an IntervalSet (e.g. bitwise ops).
109	      // Fall back to ConstIntBound to derive a safe extent.
110	      auto cib = analyzer.const_int_bound(forward_index_[i]);
111	      if (cib->min_value != arith::ConstIntBound::kNegInf &&
112	          cib->max_value != arith::ConstIntBound::kPosInf &&
113	          cib->min_value >= 0) {
114	        // extent = max - min + 1, using 64-bit integer literal
115	        ret.Set(i, Integer(cib->max_value - cib->min_value + 1));
116	      } else {
117	        // Last-resort conservative fallback to avoid OOB/crash
118	        // Prefer to keep dimension from known input_size_ if available.
119	        if (i < input_size_.size()) {
120	          ret.Set(i, input_size_[i]);
121	        } else {
122	          ret.Set(i, Integer(1));
123	        }
124	      }
125	    } else {
126	      ret.Set(i, ist.max());
127	    }
128	  }
129	  return ret;
130	}
