132	Array<PrimExpr> LayoutNode::Forward(const Array<PrimExpr> &vars) const {
133	  if (vars.empty())
134	    return forward_index_;
135	  ICHECK_GE(vars.size(), InputDim());
136	
137	  // Take the last InputDim() elements for transformation
138	  Array<PrimExpr> transform_vars;
139	  for (size_t i = vars.size() - InputDim(); i < vars.size(); i++) {
140	    transform_vars.push_back(vars[i]);
141	  }
142	
143	  Map<Var, PrimExpr> vmap;
144	  for (size_t i = 0; i < InputDim(); i++) {
145	    vmap.Set(InputPlaceholder(i), transform_vars[i]);
146	  }
147	
148	  Array<PrimExpr> transformed = forward_index_.Map(
149	      [&](const PrimExpr &e) { return Substitute(e, vmap); });
150	  // Concatenate with the remaining elements from vars
151	  Array<PrimExpr> result;
152	  for (size_t i = 0; i < vars.size() - InputDim(); i++) {
153	    result.push_back(vars[i]);
154	  }
155	  for (const auto &expr : transformed) {
156	    result.push_back(expr);
157	  }
158	
159	  return result;
160	}
