162	Fragment FragmentNode::Repeat(const Array<PrimExpr> &repeats,
163	                              bool repeat_on_thread,
164	                              bool lower_dim_first) const {
165	  ICHECK_EQ(repeats.size(), InputDim());
166	  Array<PrimExpr> new_input_size;
167	  Map<Var, PrimExpr> vmap;
168	  for (size_t i = 0; i < InputDim(); i++) {
169	    new_input_size.push_back(input_size_[i] * repeats[i]);
170	    vmap.Set(InputPlaceholder(i),
171	             FloorMod(InputPlaceholder(i), InputShape()[i]));
172	  }
173	
174	  PrimExpr repeats_index = 0, repeat_stride = 1;
175	  if (lower_dim_first) {
176	    for (int i = InputDim() - 1; i >= 0; i--) {
177	      repeats_index +=
178	          repeat_stride * FloorDiv(InputPlaceholder(i), InputShape()[i]);
179	      repeat_stride *= repeats[i];
180	    }
181	  } else {
182	    for (size_t i = 0; i < InputDim(); i++) {
183	      repeats_index +=
184	          repeat_stride * FloorDiv(InputPlaceholder(i), InputShape()[i]);
185	      repeat_stride *= repeats[i];
186	    }
187	  }
188	
189	  if (repeat_on_thread) {
190	    PrimExpr thread_size = ThreadExtent();
191	    auto new_forward_index = forward_index_.Map(
192	        [&](const PrimExpr &e) { return Substitute(e, vmap); });
193	    auto new_forward_thread =
194	        Substitute(forward_thread_, vmap) + thread_size * repeats_index;
195	    return Fragment(new_input_size, new_forward_index, new_forward_thread,
196	                    replicate_size_, std::nullopt);
197	  } else {
198	    ICHECK(OutputDim() == 1);
199	    PrimExpr frag_len = OutputShape()[0];
200	    Array<PrimExpr> new_forward_index = {Substitute(forward_index_[0], vmap) +
201	                                         frag_len * repeats_index};
202	    PrimExpr new_forward_thread = Substitute(forward_thread_, vmap);
203	    return Fragment(new_input_size, new_forward_index, new_forward_thread,
204	                    replicate_size_, std::nullopt);
205	  }
206	}
