208	Fragment FragmentNode::Replicate(int repeats) const {
209	  ICHECK(repeats >= 1);
210	  Map<Var, PrimExpr> vmap;
211	  vmap.Set(ReplicationPlaceholder(),
212	           FloorMod(ReplicationPlaceholder(), ReplicateExtent()));
213	  PrimExpr new_forward_thread =
214	      Substitute(forward_thread_, vmap) +
215	      ThreadExtent() * FloorDiv(ReplicationPlaceholder(), ReplicateExtent());
216	  return Fragment(input_size_, forward_index_, new_forward_thread,
217	                  ReplicateExtent() * repeats, std::nullopt);
218	}
