220	Fragment FragmentNode::DeReplicate() const {
221	  ICHECK(OutputDim() == 1);
222	  arith::Analyzer analyzer;
223	  UpdateAnalyzer(&analyzer);
224	  int factor = 1;
225	  auto rep_size = as_const_int(ReplicateExtent());
226	  auto idx_size = as_const_int(OutputShape()[0]);
227	  if (rep_size && idx_size) {
228	    factor = arith::ZeroAwareGCD(*rep_size, *idx_size);
229	  }
230	  if (factor == 1)
231	    return tvm::ffi::GetRef<Fragment>(this);
232	
233	  Map<Var, PrimExpr> vmap;
234	  vmap.Set(ReplicationPlaceholder(), ReplicationPlaceholder() * factor +
235	                                         FloorMod(forward_index_[0], factor));
236	  PrimExpr new_forward_thread = Substitute(forward_thread_, vmap);
237	  Array<PrimExpr> new_forward_index = {FloorDiv(forward_index_[0], factor)};
238	  return Fragment(input_size_, new_forward_index, new_forward_thread,
239	                  int(*rep_size) / factor, std::nullopt);
240	}
