248	std::pair<Layout, arith::IterMapLevel> LayoutNode::InverseWithLevel() const {
249	  arith::Analyzer analyzer;
250	  auto collect_symbolic = [&](const Array<PrimExpr> &shape) {
251	    Array<PrimExpr> symbolic_dims;
252	    for (const auto &dim : shape) {
253	      if (!as_const_int(dim)) {
254	        symbolic_dims.push_back(dim);
255	      }
256	    }
257	    return symbolic_dims;
258	  };
259	  Array<PrimExpr> symbolic_dims = collect_symbolic(input_size_);
260	  Array<PrimExpr> output_shape = OutputShape();
261	  symbolic_dims.insert(symbolic_dims.end(), output_shape.begin(),
262	                       output_shape.end());
263	  symbolic_dims = collect_symbolic(symbolic_dims);
264	  bool is_static_shape = symbolic_dims.empty();
265	  auto level = is_static_shape ? arith::IterMapLevel::Bijective
266	                               : arith::IterMapLevel::NoCheck;
267	  if (!is_static_shape) {
268	    // Runtime guards keep dynamic tails safe, so we allow NoCheck here and
269	    // warn.
270	    DLOG(WARNING) << "Layout::Inverse on symbolic layout, falling back to "
271	                     "NoCheck; symbolic dims: "
272	                  << symbolic_dims;
273	  }
274	  arith::IterMapResult res =
275	      arith::DetectIterMap(forward_index_, getVarMap(), 1, level, &analyzer);
276	  if (!res->errors.empty()) {
277	    std::ostringstream msg;
278	    msg << "Layout " << DebugOutput() << " has errors: " << res->errors;
279	    throw NormalizeIterException(msg.str());
280	  }
281	
282	  auto outputs_shape = OutputShape();
283	  Array<PrimExpr> outputs;
284	  for (size_t i = 0; i < OutputDim(); i++) {
285	    outputs.push_back(InputPlaceholder(i));
286	  }
287	
288	  auto inv = arith::InverseAffineIterMap(res->indices, outputs);
289	
290	  Array<PrimExpr> backward_index;
291	  for (size_t i = 0; i < InputDim(); i++) {
292	    if (inv.find(InputPlaceholder(i)) != inv.end()) {
293	      backward_index.push_back(inv[InputPlaceholder(i)]);
294	    } else {
295	      backward_index.push_back(0);
296	    }
297	  }
298	
299	  return {Layout(outputs_shape, backward_index), level};
300	}
