302	Layout LayoutNode::Reshape(const Array<PrimExpr> &shape,
303	                           arith::Analyzer *analyzer,
304	                           const PrimExpr rescale_num,
305	                           const PrimExpr rescale_den) const {
306	
307	  // Fast path: if shape is the same, return the original layout
308	  if (StructuralEqual()(InputShape(), shape)) {
309	    return ffi::GetRef<Layout>(this);
310	  }
311	
312	  // Step 1. Prove the product relation holds under rescale:
313	  //   prod(InputShape) * rescale_num == prod(shape) * rescale_den
314	  PrimExpr input_shape_product = Integer(1);
315	  for (const auto &dim : InputShape()) {
316	    input_shape_product *= dim;
317	  }
318	  PrimExpr shape_product = Integer(1);
319	  for (const auto &dim : shape) {
320	    shape_product *= dim;
321	  }
322	
323	  // Use provided analyzer if present, otherwise a local fallback to avoid
324	  // potential null dereference paths flagged by static analysis.
325	  arith::Analyzer fallback_analyzer;
326	  arith::Analyzer *az = analyzer ? analyzer : &fallback_analyzer;
327	  ICHECK(az->CanProveEqual(input_shape_product * rescale_num,
328	                           shape_product * rescale_den))
329	      << "InputShape() = " << InputShape() << " shape = " << shape
330	      << ", rescale_num = " << rescale_num << ", rescale_den = " << rescale_den;
331	
332	  // Step 2. Create new forward indices by reshaping
333	  // For each dimension in the new shape, we create a placeholder variable
334	  Array<Var> new_vars;
335	  new_vars.reserve(shape.size());
336	  for (size_t i = 0; i < shape.size(); ++i) {
337	    auto var = Var(std::string("n_") + std::to_string(i), shape[i].dtype());
338	    az->Bind(var, Range(0, shape[i]));
339	    new_vars.push_back(var);
340	  }
341	  // Step 3. Compute the flat index from new shape indices
342	  // flat_index = k0 * (s1 * s2 * ...) + k1 * (s2 * s3 * ...) + ... + kn
343	  PrimExpr flat_index = Integer(0);
344	  for (size_t i = 0; i < shape.size(); ++i) {
345	    PrimExpr stride = Integer(1);
346	    for (size_t j = i + 1; j < shape.size(); ++j) {
347	      stride = stride * shape[j];
348	    }
349	    flat_index = flat_index + new_vars[i] * stride;
350	  }
351	  // Convert new flat index (in units of new elements) to the old flat index
352	  // (in units of old elements) using the rational rescale factor.
353	  // old_flat = floor((flat_index * rescale_den) / rescale_num)
354	  PrimExpr old_flat_index = floordiv(flat_index * rescale_den, rescale_num);
355	  // Step 4. Convert flat index back to original shape indices
356	  // For original shape [s0, s1, ..., sm]:
357	  // i0 = flat_index // (s1 * s2 * ... * sm)
358	  // i1 = (flat_index % (s1 * s2 * ... * sm)) // (s2 * s3 * ... * sm)
359	  // ...
360	  Array<PrimExpr> original_indices;
361	  PrimExpr remaining = old_flat_index;
362	  for (size_t i = 0; i < InputShape().size(); ++i) {
363	    PrimExpr stride = Integer(1);
364	    for (size_t j = i + 1; j < InputShape().size(); ++j) {
365	      stride = stride * InputShape()[j];
366	    }
367	    original_indices.push_back(floordiv(remaining, stride));
368	    remaining = floormod(remaining, stride);
369	  }
370	  // Step 5. Substitute original indices into forward_index_
371	  Array<PrimExpr> new_forward_index;
372	  for (const auto &fwd_expr : forward_index_) {
373	    PrimExpr substituted = fwd_expr;
374	    // Replace each InputPlaceholder(i) with original_indices[i]
375	    for (size_t i = 0; i < InputShape().size(); ++i) {
376	      substituted =
377	          Substitute(substituted, {{InputPlaceholder(i), original_indices[i]}});
378	    }
379	    new_forward_index.push_back(az->Simplify(substituted));
380	  }
381	  for (size_t i = 0; i < new_vars.size(); ++i) {
382	    new_forward_index =
383	        Substitute(new_forward_index, {{new_vars[i], InputPlaceholder(i)}});
384	  }
385	  return Layout(shape, new_forward_index);
386	}
