388	Layout FragmentNode::Reshape(const Array<PrimExpr> &shape,
389	                             arith::Analyzer *analyzer,
390	                             const PrimExpr rescale_num,
391	                             const PrimExpr rescale_den) const {
392	
393	  // Fast path: identical input shape, return self
394	  if (StructuralEqual()(InputShape(), shape)) {
395	    return ffi::GetRef<Fragment>(this);
396	  }
397	
398	  // 1) Prove total number of elements remains the same
399	  PrimExpr input_prod = Integer(1);
400	  for (const auto &d : InputShape())
401	    input_prod *= d;
402	  PrimExpr shape_prod = Integer(1);
403	  for (const auto &d : shape)
404	    shape_prod *= d;
405	
406	  // Use provided analyzer if present, otherwise a local fallback.
407	  arith::Analyzer fallback_analyzer;
408	  arith::Analyzer *az = analyzer ? analyzer : &fallback_analyzer;
409	  ICHECK(az->CanProveEqual(input_prod * rescale_num, shape_prod * rescale_den))
410	      << "InputShape() = " << InputShape() << " shape = " << shape
411	      << ", rescale_num = " << rescale_num << ", rescale_den = " << rescale_den
412	      << " input fragment layout is = " << DebugOutput();
413	
414	  // 2) Build flat index from new-shape indices
415	  Array<Var> new_vars;
416	  new_vars.reserve(shape.size());
417	  for (size_t i = 0; i < shape.size(); ++i) {
418	    // Cannot use InputPlaceholder(i) here, because it would cause name capture
419	    // (variable capture) with InputPlaceholder(i) in upper scopes. Therefore,
420	    // we must create a fresh variable here to avoid confusion when
421	    // substituting.
422	    auto var = Var(std::string("n_") + std::to_string(i), shape[i].dtype());
423	    az->Bind(var, Range(0, shape[i]));
424	    new_vars.push_back(var);
425	  }
426	
427	  PrimExpr flat = Integer(0);
428	  for (size_t i = 0; i < shape.size(); ++i) {
429	    PrimExpr stride = Integer(1);
430	    for (size_t j = i + 1; j < shape.size(); ++j)
431	      stride = stride * shape[j];
432	    flat = flat + new_vars[i] * stride;
433	  }
434	  // Convert to old flat index units using the rational rescale factor.
435	  // old_flat = floor((flat * rescale_den) / rescale_num)
436	  PrimExpr old_flat = floordiv(flat * rescale_den, rescale_num);
437	  // 3) Recover original indices from flat index
438	  Array<PrimExpr> orig_indices;
439	  PrimExpr remain = old_flat;
440	  for (size_t i = 0; i < InputShape().size(); ++i) {
441	    PrimExpr stride = Integer(1);
442	    for (size_t j = i + 1; j < InputShape().size(); ++j)
443	      stride = stride * InputShape()[j];
444	    orig_indices.push_back(floordiv(remain, stride));
445	    remain = floormod(remain, stride);
446	  }
447	  // 4) Substitute old placeholders with expressions of new indices
448	  Array<PrimExpr> new_forward_index;
449	  for (const auto &e : forward_index_) {
450	    PrimExpr cur = e;
451	    for (size_t i = 0; i < InputShape().size(); ++i) {
452	      cur = Substitute(cur, {{InputPlaceholder(i), orig_indices[i]}});
453	    }
454	    cur = az->Simplify(cur);
455	    new_forward_index.push_back(cur);
456	  }
457	  PrimExpr new_forward_thread = forward_thread_;
458	  for (size_t i = 0; i < InputShape().size(); ++i) {
459	    new_forward_thread = Substitute(new_forward_thread,
460	                                    {{InputPlaceholder(i), orig_indices[i]}});
461	  }
462	  new_forward_thread = az->Simplify(new_forward_thread);
463	  for (size_t i = 0; i < new_vars.size(); ++i) {
464	    auto var = new_vars[i];
465	    new_forward_index =
466	        Substitute(new_forward_index, {{var, InputPlaceholder(i)}});
467	    new_forward_thread =
468	        Substitute(new_forward_thread, {{var, InputPlaceholder(i)}});
469	  }
470	  Fragment reshaped(shape, new_forward_index, new_forward_thread,
471	                    ReplicateExtent(), std::nullopt);
472	  if (thread_range_.defined()) {
473	    reshaped = reshaped->BindThreadRange(thread_range_);
474	  }
475	  return reshaped;
476	}
