483	PrimExpr infer_fragment_index(const Map<Var, Range> &input_iters,
484	                              const PrimExpr &forward_thread,
485	                              arith::Analyzer *analyzer) {
486	  // we build iter_vars from input_iters, but set _rep to range [0, 1)
487	  // to make it not contribute to the index of the forward_idx
488	  Array<IterVar> iter_vars;
489	  for (const auto &[var, range_] : input_iters) {
490	    Range range = range_;
491	    if (var.same_as(ReplicationPlaceholder())) {
492	      range = Range(0, 1);
493	    }
494	    iter_vars.push_back(IterVar(range, var, IterVarType::kDataPar));
495	  }
496	
497	  Array<arith::IterSplitExpr> splits =
498	      DivideUnusedIterators({forward_thread}, iter_vars, analyzer);
499	  return MakeFlattenedExpression(splits);
500	}
