502	FragmentNode::FragmentNode(Array<PrimExpr> input_size,
503	                           Array<PrimExpr> forward_index,
504	                           PrimExpr forward_thread, PrimExpr replicate_size) {
505	  input_size_ = input_size;
506	  replicate_size_ = replicate_size;
507	  arith::Analyzer analyzer;
508	  UpdateAnalyzer(&analyzer);
509	  forward_thread_ = analyzer.Simplify(forward_thread);
510	  if (forward_index.empty()) {
511	    forward_index = {
512	        infer_fragment_index(getVarMap(), forward_thread_, &analyzer)};
513	  }
514	  forward_index_ = forward_index.Map(
515	      [&](const PrimExpr &e) { return analyzer.Simplify(e); });
516	}
