518	Fragment::Fragment(Array<IterVar> forward_var, Array<PrimExpr> forward_index,
519	                   PrimExpr forward_thread, IterVar thread_replicate) {
520	  Map<Var, PrimExpr> vmap;
521	  Array<PrimExpr> input_size;
522	  PrimExpr replicate_size = 1;
523	  for (size_t i = 0; i < forward_var.size(); i++) {
524	    vmap.Set(forward_var[i]->var, InputPlaceholder(i));
525	    CHECK(is_zero(forward_var[i]->dom->min));
526	    input_size.push_back(forward_var[i]->dom->extent);
527	  }
528	  if (thread_replicate.defined()) {
529	    ICHECK(is_zero(thread_replicate->dom->min));
530	    replicate_size = thread_replicate->dom->extent;
531	    vmap.Set(thread_replicate->var, ReplicationPlaceholder());
532	  }
533	  forward_index =
534	      forward_index.Map([&](const PrimExpr &e) { return Substitute(e, vmap); });
535	  forward_thread = Substitute(forward_thread, vmap);
536	
537	  auto n = tvm::ffi::make_object<FragmentNode>(input_size, forward_index,
538	                                               forward_thread, replicate_size);
539	  data_ = std::move(n);
540	}
