542	Fragment::Fragment(Array<PrimExpr> input_size, Array<PrimExpr> forward_index,
543	                   PrimExpr forward_thread, PrimExpr replicate_size,
544	                   Optional<Var> replicate_var) {
545	  if (replicate_var.defined()) {
546	    forward_thread = Substitute(
547	        forward_thread, {{replicate_var.value(), ReplicationPlaceholder()}});
548	  }
549	  auto n = tvm::ffi::make_object<FragmentNode>(input_size, forward_index,
550	                                               forward_thread, replicate_size);
551	  data_ = std::move(n);
552	}
