554	Fragment Fragment::FullyReplicated(Array<PrimExpr> shape,
555	                                   PrimExpr thread_extent) {
556	  return Fragment(shape, {}, ReplicationPlaceholder(), thread_extent,
557	                  std::nullopt);
558	}
