566	
567	arith::IterMapResult FragmentNode::DetectInjective() const {
568	  // lei:To perform injective check, we need to reverse the layout
569	  // and use surjective check, now we use bijective check for convenience
570	  // can be relaxed in future
571	  arith::Analyzer analyzer;
572	  // Build a flat indices array: [forward_thread_, forward_index_[...]]
573	  Array<PrimExpr> indices;
574	  indices.push_back(forward_thread_);
575	  for (const auto &e : forward_index_) {
576	    indices.push_back(e);
577	  }
578	
579	  // Mirror Layout::InverseWithLevel(): if any participating shape is
580	  // symbolic, relax to NoCheck and rely on runtime guards elsewhere.
581	  auto collect_symbolic = [&](const Array<PrimExpr> &shape) {
582	    Array<PrimExpr> symbolic_dims;
583	    for (const auto &dim : shape) {
584	      if (!as_const_int(dim)) {
585	        symbolic_dims.push_back(dim);
586	      }
587	    }
588	    return symbolic_dims;
589	  };
590	
591	  Array<PrimExpr> symbolic_dims = collect_symbolic(InputShape());
592	  Array<PrimExpr> output_shape = OutputShape();
593	  symbolic_dims.insert(symbolic_dims.end(), output_shape.begin(),
594	                       output_shape.end());
595	  // Also consider replicate size for fragments
596	  if (!as_const_int(ReplicateExtent())) {
597	    symbolic_dims.push_back(ReplicateExtent());
598	  }
599	  symbolic_dims = collect_symbolic(symbolic_dims);
600	
601	  bool is_static_shape = symbolic_dims.empty();
602	  auto level = is_static_shape ? arith::IterMapLevel::Bijective
603	                               : arith::IterMapLevel::NoCheck;
604	  if (!is_static_shape) {
605	    DLOG(WARNING)
606	        << "Fragment::DetectInjective on symbolic layout, falling back to "
607	        << "NoCheck; symbolic dims: " << symbolic_dims;
608	  }
609	
610	  return arith::DetectIterMap(indices, getVarMap(), 1, level, &analyzer);
611	}
