613	PrimExpr FragmentNode::ThreadExtent() const {
614	  Array<PrimExpr> ret(OutputDim(), 1);
615	  arith::Analyzer analyzer;
616	  UpdateAnalyzer(&analyzer);
617	  auto ist = analyzer.int_set(forward_thread_ + 1);
618	  return ist.max();
619	}
