632	PrimExpr FragmentNode::ForwardThread(const Array<PrimExpr> &vars,
633	                                     const Optional<PrimExpr> &rep_var) const {
634	  Map<Var, PrimExpr> vmap;
635	  ICHECK_EQ(vars.size(), InputDim());
636	  for (size_t i = 0; i < InputDim(); i++) {
637	    vmap.Set(InputPlaceholder(i), vars[i]);
638	  }
639	  if (rep_var.defined())
640	    vmap.Set(ReplicationPlaceholder(), rep_var.value());
641	
642	  return Substitute(forward_thread_, vmap);
643	}
