650	std::pair<Layout, arith::IterMapLevel> FragmentNode::InverseWithLevel() const {
651	  auto input_size_copy = input_size_;
652	  input_size_copy.push_back(ReplicateExtent());
653	  auto forward_index_copy = forward_index_;
654	  forward_index_copy.push_back(
655	      Substitute(forward_thread_,
656	                 {{ReplicationPlaceholder(), InputPlaceholder(InputDim())}}));
657	  auto fwd = Layout(input_size_copy, forward_index_copy);
658	  return fwd->InverseWithLevel();
659	}
