661	Fragment FragmentNode::CondenseReplicateVar() const {
662	  arith::Analyzer analyzer;
663	  auto input_iters = getVarMap();
664	  input_iters.Set(ReplicationPlaceholder(), {0, ReplicateExtent()});
665	  PrimExpr new_forward_thread;
666	  IterVar new_thread_replicate;
667	  std::tie(new_forward_thread, new_thread_replicate) =
668	      CompressIterator(forward_thread_, ToIterVars(input_iters),
669	                       ReplicationPlaceholder(), &analyzer);
670	  return Fragment(input_size_, forward_index_, new_forward_thread,
671	                  new_thread_replicate->dom->extent, new_thread_replicate->var);
672	}
