695	bool LayoutNode::IsEqual(const LayoutNode *other, bool skip_index) const {
696	  bool ret = StructuralEqual()(this->InputShape(), other->InputShape());
697	  ret &= StructuralEqual()(this->OutputShape(), other->OutputShape());
698	  if (!ret) {
699	    return false;
700	  }
701	  if (!skip_index) {
702	    // Create common variables for comparison. Using Forward with common
703	    // variables ensures we compare the actual mapping rather than AST
704	    // structure, since InputPlaceholder may compare equal in StructuralEqual.
705	    Array<PrimExpr> common_vars;
706	    for (size_t i = 0; i < this->InputDim(); i++) {
707	      common_vars.push_back(Var("_cmp_v" + std::to_string(i)));
708	    }
709	
710	    auto this_forward = this->Forward(common_vars);
711	    auto other_forward = other->Forward(common_vars);
712	
713	    if (!StructuralEqual()(this_forward, other_forward)) {
714	      return false;
715	    }
716	  }
717	  return ret;
718	}
719	
720	bool FragmentNode::IsEqual(const FragmentNode *other, bool skip_index) const {
721	  // Fragment Layout Comparison can skip the index comparison
722	  // when the output shape is the same, as we can do
723	  // a[i, j] = b[j, i] in register level.
724	
725	  bool ret = StructuralEqual()(this->InputShape(), other->InputShape());
726	  if (!ret) {
727	    // may be broadcast case
728	    return true;
729	  }
730	  if (this->thread_range_.defined() && other->thread_range_.defined()) {
731	    ret &= StructuralEqual()(this->thread_range_, other->thread_range_);
732	  }
733	  ret &= StructuralEqual()(this->OutputShape(), other->OutputShape());
734	  ret &= StructuralEqual()(this->ReplicateExtent(), other->ReplicateExtent());
735	  ret &= StructuralEqual()(this->ThreadExtent(), other->ThreadExtent());
736	  if (!ret) {
737	    return false;
738	  }
739	  if (!skip_index) {
740	    // Create common variables for comparison. Using Forward/ForwardThread with
741	    // common variables ensures we compare the actual mapping rather than AST
742	    // structure, since InputPlaceholder may compare equal in StructuralEqual.
743	    Array<PrimExpr> common_vars;
744	    for (size_t i = 0; i < this->InputDim(); i++) {
745	      common_vars.push_back(Var("_cmp_v" + std::to_string(i)));
746	    }
747	    Var common_rep("_cmp_rep");
748	
749	    auto this_forward = this->Forward(common_vars);
750	    auto other_forward = other->Forward(common_vars);
751	
752	    if (!StructuralEqual()(this_forward, other_forward)) {
753	      return false;
754	    }
755	
756	    // Also compare forward_thread mapping.
757	    auto this_thread = this->ForwardThread(common_vars, common_rep);
758	    auto other_thread = other->ForwardThread(common_vars, common_rep);
759	    if (!StructuralEqual()(this_thread, other_thread)) {
760	      return false;
761	    }
762	  }
763	  return ret;
764	}
