74	  void RunInferStep(int cur_infer_id, InferLevel level, bool update_queue,
75	                    LayoutMap &layout_map, const LayoutMap &strict_layout_map,
76	                    std::deque<int> &q, std::vector<bool> &in_queue) {
77	    auto num_infer = infer_list_.size();
78	
79	    // Range check for cur_infer_id
80	    ICHECK_GE(cur_infer_id, 0) << "cur_infer_id is negative, which is invalid.";
81	    ICHECK_LT(cur_infer_id, num_infer)
82	        << "cur_infer_id " << cur_infer_id << " is out of range, must be < "
83	        << num_infer << ".";
84	
85	    // Make sure we can safely access infer_list_[cur_infer_id] and
86	    // thread_var_vec_[cur_infer_id]
87	    auto &next = infer_list_[cur_infer_id];
88	    auto iter_var = thread_var_vec_[cur_infer_id];
89	    auto thread_bounds = thread_bounds_vec_[cur_infer_id];
90	    arith::Analyzer *cur_analyzer = analyzer_vec_[cur_infer_id].get();
91	    auto buffer_oob = buffer_oob_vec_[cur_infer_id];
92	    // Double-check that 'next' is valid
93	    ICHECK(next.defined()) << "infer_list_[" << cur_infer_id
94	                           << "] is null inside run_infer_step.";
95	
96	    // Check iter_var->dom and dom->extent
97	    ICHECK(iter_var.defined())
98	        << "thread_var_vec_[" << cur_infer_id << "] is not defined.";
99	    ICHECK(iter_var->dom.defined())
100	        << "iter_var->dom is not defined for infer_list_[" << cur_infer_id
101	        << "].";
102	    ICHECK(iter_var->dom->extent.defined())
103	        << "iter_var->dom->extent is not defined for infer_list_["
104	        << cur_infer_id << "].";
105	
106	    const int64_t *extent_ptr = as_const_int(iter_var->dom->extent);
